// Verify stock Scratch RUN behavior and artifact fidelity. All files generated by
// this script go under local/; the release archive is never overwritten.
const assert = require('node:assert/strict');
const fs = require('node:fs'), path = require('node:path'), crypto = require('node:crypto');
const {spawnSync} = require('node:child_process');
const {zipRead} = require('../../sb3lib.js');
const here = __dirname, work = path.dirname(here), root = path.resolve(work, '../..'), local = path.join(here,'local');
const base = path.join(root,'MiniPy_v4.257.sb3'), release = path.join(root,'MiniPy_v4.258.sb3');
const py = process.env.MINIPY_PYTHON || 'python', node = process.execPath;
const env = {...process.env, PYTHONUTF8:'1', PYTHONDONTWRITEBYTECODE:'1', MINIPY_MAX_MS:'30000'};
delete env.MINIPY_VM;
fs.mkdirSync(local,{recursive:true});
const file = n=>path.join(local,n), json = p=>JSON.parse(fs.readFileSync(p,'utf8'));
const hash = (bytes,alg='sha256')=>crypto.createHash(alg).update(bytes).digest('hex');
function run(exe,args,accept=[0]) {
  const p=spawnSync(exe,args,{cwd:root,env,encoding:'utf8',maxBuffer:32*1024*1024,windowsHide:true});
  if(p.error) throw p.error;
  if(!accept.includes(p.status))throw Error(`${path.basename(args[0])}: exit=${p.status}\n${p.stdout.slice(-2000)}\n${p.stderr.slice(-2000)}`);
  return p.stdout;
}
function pkg(p) {
  const entries=zipRead(p), assets=new Map(); assert.equal(entries.length,new Set(entries.map(x=>x.name)).size);
  for(const e of entries)if(e.name!=='project.json') {assert.equal(hash(e.data,'md5'),e.name.split('.')[0]);assets.set(e.name,hash(e.data));}
  const project=JSON.parse(entries.find(e=>e.name==='project.json').data);
  for(const t of project.targets)for(const a of [...t.costumes,...t.sounds])assert.ok(assets.has(a.md5ext)&&a.assetId===a.md5ext.split('.')[0]);
  return {project,assets};
}
function replay(sb,suite,label) {
  const transcript=run(node,[path.join(work,'v253/replay.cjs'),sb,suite],[0,1]);
  fs.writeFileSync(file(`${label}.log`),transcript);
  const results=transcript.split(/\r?\n/).filter(l=>l.startsWith('{')).map(l=>JSON.parse(l));
  const input=json(suite);assert.deepEqual(results.map(x=>x.name),input.map(x=>x.name));assert.ok(results.every(x=>x.completed),`timeout: ${label}`);
  const failed=results.filter(x=>!x.pass).map(x=>x.name),passed=results.length-failed.length;
  assert.ok(transcript.includes(`${passed}/${results.length} passed`));console.log(`${label}: ${passed}/${results.length}`);
  return {passed,total:results.length,failed};
}
const baselineHash=hash(fs.readFileSync(base));assert.equal(baselineHash,'dafb0f0089087c03febeaae0bb80462db450ca4e4b62486a8620caef8f7d5173');
const oracle=run(py,['-X','utf8',path.join(here,'make-edges.py'),'--check']).trim().split(/\r?\n/);console.log(...oracle);
run(node,[path.join(here,'build.cjs'),file('rebuilt.sb3')]);assert.ok(fs.readFileSync(release).equals(fs.readFileSync(file('rebuilt.sb3'))),'non-reproducible release');
const old=pkg(base),fresh=pkg(release);assert.deepEqual(old.assets,fresh.assets);assert.equal(fresh.project.meta.agent,'MiniPy v4.258');
assert.deepEqual(fresh.project.targets.map(t=>t.name),old.project.targets.map(t=>t.name));
for(const [i,t] of fresh.project.targets.entries()) {const before=old.project.targets[i];if(t.name!=='Interpreter')assert.deepEqual(t,before);
  else {const nonCode=({blocks,variables,lists,...rest})=>rest;assert.deepEqual(nonCode(t),nonCode(before));}}
const structure=run(node,[path.join(work,'check41.cjs'),release]);assert.match(structure,/errors=0/);
run(node,[path.join(work,'v253/archive-suite.cjs'),file('archive.json')]);run(py,['-X','utf8',path.join(work,'v254/fold-suite.py'),file('fold.json')]);
const report=path.join(work,'v257/report.json'), prev=json(path.join(work,'v257/verification.json'));
const failures=[];
const names=json(report).map(x=>x.name);assert.equal(names.length,586);assert.equal(new Set(names).size,586);
const baseline=replay(base,report,'baseline-report'),candidate=replay(release,report,'candidate-report');
assert.deepEqual(baseline.failed,failures);assert.deepEqual(candidate.failed,[]);
const stressNames=names.filter(n=>n.startsWith('R3/T'));assert.equal(stressNames.length,20);
const mainBaseline=replay(base,path.join(here,'edge-cases.json'),'baseline-mainname');
assert.deepEqual(mainBaseline.failed,['main-guard','main-value','function-global','class-global','main-inequality','main-as-argument','main-string-method','main-format']);
const mainCandidate=replay(release,path.join(here,'edge-cases.json'),'candidate-mainname');assert.deepEqual(mainCandidate.failed,[]);
const repeatOutput=run(node,[path.join(here,'repeat-run.cjs'),release]);fs.writeFileSync(file('repeat-run.log'),repeatOutput);
const repeated=repeatOutput.split(/\r?\n/).filter(l=>l.startsWith('{')).map(JSON.parse).at(-1);
assert.deepEqual(repeated,{sameVmRuns:2,first:['__main__','changed'],second:['__main__','guard'],pass:true});
const edges=mainCandidate;
const suites=prev.previous.suites;
const previous=Object.entries(suites).flatMap(([name,size])=>{const input=json(name.endsWith('.py')?file('fold.json'):path.join(work,name));assert.equal(input.length,size);
  return input.map(c=>({...c,name:`${name}: ${c.name}`}));});
fs.writeFileSync(file('previous.json'),JSON.stringify(previous));const history=replay(release,file('previous.json'),'previous');assert.deepEqual(history.failed,[]);
const archive=replay(release,file('archive.json'),'archive-final');assert.deepEqual([...archive.failed].sort(),[...prev.archive.failed].sort());
const proof={baseline:{version:'4.257',commit:'768dce19d6ee2fc02c114ace4516730c9b4387c7',sha256:baselineHash},
  candidate:{version:'4.258',bytes:fs.statSync(release).size,sha256:hash(fs.readFileSync(release)),blocks:Number(structure.match(/total blocks=(\d+)/)[1]),
    structuralErrors:0,unchangedAssets:fresh.assets.size,unchangedOtherTargets:true,unchangedCostumes:true,byteIdenticalRebuild:true},
  environment:{node:process.versions.node,scratchVm:require('../../vm5300/node_modules/scratch-vm/package.json').version,oracle,entry:'Stock Scratch VM; RUN broadcast'},
  report:{sourceSha256:'358bd42952b04a125b28f2d96e8ce0bb1382a795534e27303ef090f7252434f2',baseline,candidate,stressIncluded:stressNames.length},
  initialization:{baseline:mainBaseline,candidate:mainCandidate,repeated},
  previous:{suites,...history},archive:{...archive,changedPassStatusFrom257:[]}};
fs.writeFileSync(file('verification.json'),JSON.stringify(proof,null,2)+'\n');console.log(`Verification complete: ${file('verification.json')}`);
